#!/bin/sh
# memprobe.sh - run a command and emit memory MEASURE lines (meant to run inside the measured container).
# usage: memprobe.sh [--settle S[,S...]] [--interval S] [--boundary-file F | --boundary-line STR] -- cmd [args...]
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'memprobe.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'memprobe.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: memprobe.sh [--settle S[,S...]] [--interval S] [--boundary-file F | --boundary-line STR] -- cmd [args...]
       memprobe.sh --help | --build | --version

Runs cmd, samples the container's cgroup v2 files and the command's /proc status every --interval seconds
(default 0.5), and prints MEASURE lines after the command exits. The command's exit status is the probe's.

  --interval S         sampling period in seconds, a positive decimal (default 0.5)
  --boundary-file F    workload-complete marker: the command creates file F (which must not exist at start)
  --boundary-line STR  workload-complete marker: the command prints the exact line STR on stdout
                       (stdout is passed through; the command must flush it)
  --settle S[,S...]    settle windows, non-negative whole seconds after the boundary (default 0 when a
                       boundary option is given; requires a boundary option)

Boundary and settled metrics: the command must keep running through every settle window; a window is sampled
at the first sample at or after boundary+S, only while the command is alive. A window not reached before the
command exits, or any window without a boundary, is not emitted (stderr note: unsupported).

Metrics (MiB, two decimals; cgroup values are container-level and include the probe and page cache):
  cgroup_peak_mib            memory.peak read after the command exits (anon + file high-water, kernel-kept)
  cgroup_anon_hwm_mib        highest sampled "anon" of memory.stat
  cgroup_file_hwm_mib        highest sampled "file" of memory.stat
  vmhwm_mib                  the command's VmHWM at its last sample before exit (the command must be the
                             process itself, not a shell wrapper; a process that exits between samples
                             can miss its final growth)
  anon_settled_<S>s_mib      cgroup memory.stat "anon" at the first sample at/after boundary+S
  rssanon_settled_<S>s_mib   the command's RssAnon at the same sample
A cgroup file that is missing is reported on stderr and its metrics are not emitted.
Exit status 2: usage error. --build/--version print the repo's last-commit id (-dirty if modified, unknown
without git).
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
build_id() {
  d=$(git --no-optional-locks -C "$HERE" rev-parse --show-toplevel 2>/dev/null) || d=
  [ -n "$d" ] || { echo unknown; return; }
  sha=$(git --no-optional-locks -C "$d" log -1 --format=%H -- "$d" 2>/dev/null) || sha=
  [ -n "$sha" ] || { echo unknown; return; }
  if [ -n "$(git --no-optional-locks -C "$d" status --porcelain --untracked-files=no -- "$d" 2>/dev/null)" ]; then echo "$sha-dirty"; else echo "$sha"; fi
}
case ${1:-} in
  --build|--version) build_id; exit 0 ;;
esac

usage() { echo "memprobe.sh: $*" >&2; echo "usage: memprobe.sh [--settle S[,S...]] [--interval S] [--boundary-file F | --boundary-line STR] -- cmd [args...] (try --help)" >&2; exit 2; }

interval=0.5; settle=; bfile=; bline=; have_bline=0
while [ $# -gt 0 ]; do
  case $1 in
    --) shift; break ;;
    --interval) [ $# -ge 2 ] || usage "--interval needs a value"; interval=$2; shift 2 ;;
    --settle) [ $# -ge 2 ] || usage "--settle needs a value"; settle=$2; shift 2 ;;
    --boundary-file) [ $# -ge 2 ] || usage "--boundary-file needs a value"; bfile=$2; shift 2 ;;
    --boundary-line) [ $# -ge 2 ] || usage "--boundary-line needs a value"; bline=$2; have_bline=1; shift 2 ;;
    *) usage "unknown argument '$1'" ;;
  esac
done
[ $# -gt 0 ] || usage "missing command after --"
case $interval in ''|*[!0-9.]*|.|*.*.*|.*|*.) usage "--interval must be a positive decimal, got '$interval'" ;; esac
case $interval in *[1-9]*) ;; *) usage "--interval must be positive, got '$interval'" ;; esac
if [ -n "$bfile" ] && [ "$have_bline" = 1 ]; then usage "--boundary-file and --boundary-line are exclusive"; fi
if [ "$have_bline" = 1 ] && [ -z "$bline" ]; then usage "--boundary-line must not be empty"; fi
if [ -n "$bfile" ] && [ -e "$bfile" ]; then usage "boundary file '$bfile' already exists"; fi
if [ -z "$bfile" ] && [ "$have_bline" = 0 ]; then
  [ -z "$settle" ] || usage "--settle requires --boundary-file or --boundary-line"
else
  [ -n "$settle" ] || settle=0
fi
wins=
if [ -n "$settle" ]; then
  case $settle in ,*|*,|*,,*) usage "--settle has an empty element: '$settle'" ;; esac
  oldifs=$IFS; IFS=,
  # shellcheck disable=SC2086
  set -- $settle -- "$@"
  IFS=$oldifs
  while [ "$1" != "--" ]; do
    w=$1
    case $w in ''|*[!0-9]*) usage "--settle values must be non-negative whole seconds, got '$w'" ;; esac
    while :; do case $w in 0?*) w=${w#0} ;; *) break ;; esac; done
    case " $wins " in *" $w "*) usage "duplicate settle window $w" ;; esac
    wins="$wins $w"; shift
  done
  shift
fi

CG=/sys/fs/cgroup
have_stat=0; have_peak=0
[ -r "$CG/memory.stat" ] && have_stat=1 || echo "memprobe: $CG/memory.stat not readable; cgroup anon/file metrics not emitted" >&2
[ -r "$CG/memory.peak" ] && have_peak=1 || echo "memprobe: $CG/memory.peak not readable; cgroup_peak_mib not emitted" >&2

T=$(mktemp -d)
pid=; reader=
cleanup() { rm -rf "$T"; }
trap cleanup EXIT
if [ "$have_bline" = 1 ]; then
  mkfifo "$T/out"
  # the reader passes the command's stdout through and drops a marker at the boundary line
  ( while IFS= read -r l; do printf '%s\n' "$l"; if [ "$l" = "$bline" ]; then : >"$T/boundary"; fi; done <"$T/out"
    [ -z "$l" ] || printf '%s\n' "$l" ) &
  reader=$!
  "$@" >"$T/out" &
  pid=$!
else
  "$@" &
  pid=$!
fi
trap 'kill -TERM "$pid" 2>/dev/null || true' INT TERM

cg_anon=0; cg_file=0; anon_hwm=0; file_hwm=0; hwm_kb=0; rssanon_kb=0; st=
tb=; up=0; pending=$wins; settled=
sample_cg() {
  [ "$have_stat" = 1 ] || return 0
  while read -r k v; do
    case $k in anon) cg_anon=$v ;; file) cg_file=$v ;; esac
  done <"$CG/memory.stat"
  if [ "$cg_anon" -gt "$anon_hwm" ]; then anon_hwm=$cg_anon; fi
  if [ "$cg_file" -gt "$file_hwm" ]; then file_hwm=$cg_file; fi
}
sample_proc() { # returns 1 when the process is gone or a zombie
  [ -r "/proc/$pid/status" ] || return 1
  p_hwm=; p_anon=; st=
  while read -r k v _; do
    case $k in VmHWM:) p_hwm=$v ;; RssAnon:) p_anon=$v ;; State:) st=$v ;; esac
  done <"/proc/$pid/status" 2>/dev/null || return 1
  case $st in Z*|'') return 1 ;; esac
  if [ -n "$p_hwm" ]; then hwm_kb=$p_hwm; fi
  if [ -n "$p_anon" ]; then rssanon_kb=$p_anon; fi
  return 0
}
boundary_seen() {
  if [ -n "$bfile" ]; then [ -e "$bfile" ]; else [ -e "$T/boundary" ]; fi
}
while :; do
  sample_proc || break
  sample_cg
  read -r up _ </proc/uptime; up=${up%.*}${up#*.}
  if [ -z "$tb" ] && [ -n "$pending" ] && boundary_seen; then tb=$up; fi
  if [ -n "$tb" ] && [ -n "$pending" ]; then
    rest=
    for w in $pending; do
      if [ $((up - tb)) -ge $((w * 100)) ]; then
        settled="$settled$w $cg_anon $rssanon_kb
"
      else
        rest="$rest $w"
      fi
    done
    pending=$rest
  fi
  sleep "$interval"
done
rc=0
wait "$pid" || rc=$?
if [ -n "$reader" ]; then wait "$reader" || true; fi
peak=
if [ "$have_peak" = 1 ]; then read -r peak <"$CG/memory.peak" || peak=; fi

if [ -z "$bfile" ] && [ "$have_bline" = 0 ]; then
  :
elif [ -z "$tb" ]; then
  echo "memprobe: settled metrics unsupported: the command gave no boundary before it exited" >&2
fi
for w in $pending; do
  [ -z "$tb" ] || echo "memprobe: settle window ${w}s not reached: the command exited before boundary+${w}s (unsupported, not emitted)" >&2
done
mib_b() { awk -v v="$1" 'BEGIN{printf "%.2f", v/1048576}'; }
mib_k() { awk -v v="$1" 'BEGIN{printf "%.2f", v/1024}'; }
[ -z "$peak" ] || echo "MEASURE cgroup_peak_mib $(mib_b "$peak") MiB"
if [ "$have_stat" = 1 ]; then
  echo "MEASURE cgroup_anon_hwm_mib $(mib_b "$anon_hwm") MiB"
  echo "MEASURE cgroup_file_hwm_mib $(mib_b "$file_hwm") MiB"
fi
echo "MEASURE vmhwm_mib $(mib_k "$hwm_kb") MiB"
printf '%s' "$settled" | while read -r w a r; do
  [ -n "$w" ] || continue
  [ "$have_stat" = 0 ] || echo "MEASURE anon_settled_${w}s_mib $(mib_b "$a") MiB"
  echo "MEASURE rssanon_settled_${w}s_mib $(mib_k "$r") MiB"
done
exit "$rc"
